/// adopting it moved no reference image and changed neither the full-screen viewport
/// nor the 160 × 112 floating window. It only ever pulls back, and only for a host
/// taller than it is wide.
static func distance(radius: Float, aspect: Float) -> Float {
    let vertical = verticalFieldOfView
    let horizontal = 2 * atan(tan(vertical / 2) * max(aspect, 0.01))
    return radius / sin(min(vertical, horizontal) / 2) * 1.1
}

