import CoreGraphics
import Foundation
import ImageIO

func load(_ path: String) -> (w: Int, h: Int, px: [UInt8])? {
    guard let src = CGImageSourceCreateWithURL(URL(fileURLWithPath: path) as CFURL, nil),
          let img = CGImageSourceCreateImageAtIndex(src, 0, nil) else { return nil }
    let w = img.width, h = img.height
    var px = [UInt8](repeating: 0, count: w * h * 4)
    let cs = CGColorSpaceCreateDeviceRGB()
    guard let ctx = CGContext(
        data: &px, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
        space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
    ) else { return nil }
    ctx.draw(img, in: CGRect(x: 0, y: 0, width: w, height: h))
    return (w, h, px)
}

let args = CommandLine.arguments
guard args.count == 3, let a = load(args[1]), let b = load(args[2]) else {
    print("usage: pngdiff OLD NEW"); exit(1)
}
guard a.w == b.w, a.h == b.h else {
    print("size differs: \(a.w)x\(a.h) vs \(b.w)x\(b.h)"); exit(0)
}

var maxDelta = 0
var count = 0
var minX = a.w, minY = a.h, maxX = -1, maxY = -1
for y in 0 ..< a.h {
    for x in 0 ..< a.w {
        let i = (y * a.w + x) * 4
        var d = 0
        for c in 0 ..< 3 { d = max(d, abs(Int(a.px[i + c]) - Int(b.px[i + c]))) }
        if d > 0 {
            count += 1
            maxDelta = max(maxDelta, d)
            minX = min(minX, x); maxX = max(maxX, x)
            minY = min(minY, y); maxY = max(maxY, y)
        }
    }
}
if count == 0 {
    print("identical")
} else {
    let pct = Double(count) / Double(a.w * a.h) * 100
    print("differing px: \(count) (\(String(format: "%.1f", pct))%)  maxDelta: \(maxDelta)/255")
    print("bounding box: x \(minX)…\(maxX)  y \(minY)…\(maxY)   of \(a.w)x\(a.h)")
}
